const results = [];

for (const item of $input.all()) {
  const data = item.json.data || item.json;

  // Handle if data is array or object with sections
  const sections = data.sections || (data.data && data.data.sections);

  if (sections) {
    for (const section of sections) {
      if (section.layout_content && section.layout_content.medias) {
        for (const mediaWrapper of section.layout_content.medias) {
          if (mediaWrapper.media) {
             const media = mediaWrapper.media;

             let imageUrl = null;
             if (media.image_versions2 && media.image_versions2.candidates && media.image_versions2.candidates.length > 0) {
                 imageUrl = media.image_versions2.candidates[0].url;
             }

             let videoUrl = null;
             if (media.video_versions && media.video_versions.length > 0) {
                 videoUrl = media.video_versions[0].url;
             }

             results.push({
               json: {
                 id: media.id,
                 pk: media.pk,
                 code: media.code,
                 url: `https://www.instagram.com/p/${media.code}/`,
                 caption: media.caption ? media.caption.text : '',
                 username: media.user ? media.user.username : '',
                 full_name: media.user ? media.user.full_name : '',
                 like_count: media.like_count,
                 comment_count: media.comment_count,
                 play_count: media.play_count,
                 media_type: media.media_type,
                 image_url: imageUrl,
                 video_url: videoUrl
               }
             });
          }
        }
      }
    }
  }
}

// Debug info if results are empty
if (results.length === 0) {
    return [
        {
            json: {
                debug: "No results found",
                input_structure: $input.all().map(i => Object.keys(i.json))
            }
        }
    ];
}

return results;

const allItems = $input.all();
const existingUrls = new Set();
const newCandidates = [];

// First pass: Identify existing URLs and collect candidates
for (const item of allItems) {
    const json = item.json;

    // Check if it's an existing Google Sheet item
    // Existing items have 'VideoURL' or 'row_number'
    if (json.row_number !== undefined || json.VideoURL !== undefined) {
        if (json.VideoURL && json.VideoURL.trim() !== '') {
            existingUrls.add(json.VideoURL.trim());
        }
    }
    // Check if it's a new item from the scraper (Success Output)
    // It must have 'Post URL'
    else if (json["Post URL"]) {
        newCandidates.push(item);
    }
}

const uniqueItems = [];

// Second pass: Filter candidates
for (const item of newCandidates) {
    const url = item.json["Post URL"];

    if (url && !existingUrls.has(url)) {
        uniqueItems.push({
            json: {
                VideoURL: url,
                Caption: item.json["Caption"],
                Like: item.json["Likes"],
                CM: item.json["Comments"],
                View: item.json["Views"] || 0,
                Date: new Date().toISOString().split('T')[0]
            }
        });
        // Add to set to prevent duplicates within the new batch itself
        existingUrls.add(url);
    }
}

return uniqueItems;
